using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelService>();
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>();

var app = builder.Build();

// Train the model at startup and configure the prediction engine pool
var modelService = app.Services.GetRequiredService<TicketModelService>();
var metrics = modelService.TrainAndEvaluate();
app.Logger.LogInformation(
    "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
    metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

app.MapControllers();
app.Run();

